CE(ponto_seguida, 0) + COALESCE(ponto_paragrafo, 0) + COALESCE(ponto_virgula, 0) +\\n    COALESCE(reticencias, 0) + COALESCE(ponto_interrogacao, 0) + COALESCE(ponto_exclamacao, 0) +\\n    COALESCE(travessao, 0) + COALESCE(aspas, 0) + COALESCE(parenteses, 0) +\\n    COALESCE(usualidade, 0) + COALESCE(portunhol, 0) + COALESCE(extra_terrestre, 0) +\\n    COALESCE(repeticoes_inadequadas, 0) + COALESCE(ausencia, 0) + COALESCE(excesso, 0) + COALESCE(ordem, 0)\\n  ) AS `sum`\\nFROM\\n  `caracterizacao_escritura`\\nWHERE\\n  1 = 1\\n  [[AND `N√≠vel` = {{nivel}}]]\\n  [[AND `Professor(a)` = {{profesor}}]]\\n  [[AND ano_semestre = {{ano_semestre}}]]\\n  [[AND `Hor√°rio` = {{horario}}]]\\n  [[AND corte = {{corte}}]]\\n  [[AND email = {{Email}}]]\\n\\nORDER BY\"},\"parameters\":[{\"id\":\"a1462b6b-3647-4e5c-9359-3890365f904e\",\"type\":\"category\",\"value\":null,\"target\":[\"variable\",[\"template-tag\",\"nivel\"]]},{\"id\":\"b6bbed08-d2d6-47d5-a9aa-f2f0239701e6\",\"type\":\"category\",\"value\":null,\"target\":[\"variable\",[\"template-tag\",\"profesor\"]]},{\"id\":\"51962203-f53d-4f3a-beeb-3726f4c73fc6\",\"type\":\"category\",\"value\":null,\"target\":[\"variable\",[\"template-tag\",\"ano_semestre\"]]},{\"id\":\"954a7e5e-8c66-493f-8529-d860b0ec4f9c\",\"type\":\"category\",\"value\":null,\"target\":[\"variable\",[\"template-tag\",\"horario\"]]},{\"id\":\"b2be97c5-b674-44b3-b393-ec0f51047a5d\",\"type\":\"category\",\"value\":null,\"target\":[\"variable\",[\"template-tag\",\"corte\"]]},{\"id\":\"d3207d00-bb8b-4a2a-83d2-b37a08b8cf22\",\"type\":\"category\",\"value\":null,\"target\":[\"variable\",[\"template-tag\",\"Email\"]]}],\"middleware\":{\"js-int-to-string?\":true,\"userland-query?\":true,\"add-default-userland-constraints?\":true}}'),(_binary '>ô2{es\ÿHMwd´Ç\Z{Vnkú°<-}\‰|Ñ˛',46,'{\"constraints\":{\"max-results\":10000,\"max-results-bare-rows\":2000},\"type\":\"native\",\"middleware\":{\"js-int-to-string?\":true,\"ignore-cached-results?\":false,\"process-viz-settings?