\r\\n  [[AND `Ano_Semestre` = {{ano_semestre}}]] \\r\\n  [[AND `Hor√°rio` = {{horario}}]] \\r\\n  [[AND `Corte` = {{corte}}]]\\r\\n  [[AND `Nome` = {{Nome}}]]\\r\\n\\r\\nUNION ALL\\r\\n\\r\\n-- CONCORDANCIA NOMINAL\\r\\nSELECT \'CONC_NOMINAL\', \\r\\n       SUM(genero + numero)\\r\\nFROM caracterizacao_escritura\\r\\nWHERE 1=1\\r\\n  [[AND `N√≠vel` = {{nivel}}]] \\r\\n  [[AND `Professor(a)` = {{profesor}}]] \\r\\n  [[AND `Ano_Semestre` = {{ano_semestre}}]] \\r\\n  [[AND `Hor√°rio` = {{horario}}]] \\r\\n  [[AND `Corte` = {{corte}}]]\\r\\n  [[AND `Nome` = {{Nome}}]]\\r\\n\\r\\nUNION ALL\\r\\n\\r\\n-- PUNTUACI√ìN\\r\\nSELECT \'PONTUACAO\', \\r\\n       SUM(virgula + ponto_seguida + ponto_paragrafo + ponto_virgula + \\r\\n           reticencias + ponto_interrogacao + ponto_exclamacao + travessao + \\r\\n           aspas + parenteses)\\r\\nFROM caracterizacao_escritura\\r\\nWHERE 1=1\\r\\n  [[AND `N√≠vel` = {{nivel}}]] \\r\\n  [[AND `Professor(a)` = {{profesor}}]] \\r\\n  [[AND `Ano_Semestre` = {{ano_semestre}}]] \\r\\n  [[AND `Hor√°rio` = {{horario}}]] \\r\\n  [[AND `Corte` = {{corte}}]]\\r\\n  [[AND `Nome` = {{Nome}}]]\\r\\n\\r\\nUNION ALL\\r\\n\\r\\n-- VOCABULARIO\\r\\nSELECT \'VOCABULARIO\', \\r\\n       SUM(usualidade + portunhol + extra_terrestre + repeticoes_inadequadas + \\r\\n           ausencia + excesso + ordem)\\r\\nFROM caracterizacao_escritura\\r\\nWHERE 1=1\\r\\n  [[AND `N√≠vel` = {{nivel}}]] \\r\\n  [[AND `Professor(a)` = {{profesor}}]] \\r\\n  [[AND `Ano_Semestre` = {{ano_semestre}}]] \\r\\n  [[AND `Hor√°rio` = {{horario}}]] \\r\\n  [[AND `Corte` = {{corte}}]]\\r\\n  [[AND `Nome` = {{Nome}}]]\"},\"viz-settings\":{\"graph.dimensions\":[\"categoria\"],\"graph.show_values\":true,\"graph.x_axis.title_text\":\"CATEGORIA\",\"graph.metrics\":[\"total_erros\"]},\"database\":33,\"parameters\":[{\"id\":\"e03c1a21-7ca2-4f66-933c-d844f0e9cbbd\",\"type\":\"category\",\"target\":[\"variable\",[\"template-tag\",\"nivel\"]],\"value\":null},{\"id\":\"c779d0ce-0dce-4c00-9