results\":10000,\"max-results-bare-rows\":2000},\"type\":\"native\",\"middleware\":{\"js-int-to-string?\":true,\"ignore-cached-results?\":false,\"userland-query?\":true},\"cache-strategy\":null,\"native\":{\"template-tags\":{\"nivel\":{\"type\":\"text\",\"name\":\"nivel\",\"id\":\"a1462b6b-3647-4e5c-9359-3890365f904e\",\"display-name\":\"Nivel\"},\"profesor\":{\"type\":\"text\",\"name\":\"profesor\",\"id\":\"b6bbed08-d2d6-47d5-a9aa-f2f0239701e6\",\"display-name\":\"Profesor\"},\"ano_semestre\":{\"type\":\"text\",\"name\":\"ano_semestre\",\"id\":\"51962203-f53d-4f3a-beeb-3726f4c73fc6\",\"display-name\":\"Ano Semestre\"},\"horario\":{\"type\":\"text\",\"name\":\"horario\",\"id\":\"954a7e5e-8c66-493f-8529-d860b0ec4f9c\",\"display-name\":\"Horario\"},\"corte\":{\"type\":\"text\",\"name\":\"corte\",\"id\":\"b2be97c5-b674-44b3-b393-ec0f51047a5d\",\"display-name\":\"Corte\"},\"Email\":{\"type\":\"text\",\"name\":\"Email\",\"id\":\"d3207d00-bb8b-4a2a-83d2-b37a08b8cf22\",\"display-name\":\"Email\"}},\"query\":\"-- Total por cada profesor(a)\\nSELECT\\n  `Professor(a)` AS `Professor`,\\n  SUM(\\n    COALESCE(ss, 0) + COALESCE(√ß, 0) + COALESCE(rr, 0) + COALESCE(x, 0) + COALESCE(s, 0) +\\n    COALESCE(acento_grave, 0) + COALESCE(acento_agudo, 0) + COALESCE(acento_circunflexo, 0) + COALESCE(til, 0) +\\n    COALESCE(verbos_regulares, 0) + COALESCE(verbos_irregulares, 0) +\\n    COALESCE(genero, 0) + COALESCE(numero, 0) +\\n    COALESCE(virgula, 0) + COALESCE(ponto_seguida, 0) + COALESCE(ponto_paragrafo, 0) + COALESCE(ponto_virgula, 0) +\\n    COALESCE(reticencias, 0) + COALESCE(ponto_interrogacao, 0) + COALESCE(ponto_exclamacao, 0) +\\n    COALESCE(travessao, 0) + COALESCE(aspas, 0) + COALESCE(parenteses, 0) +\\n    COALESCE(usualidade, 0) + COALESCE(portunhol, 0) + COALESCE(extra_terrestre, 0) +\\n    COALESCE(repeticoes_inadequadas, 0) + COALESCE(ausencia, 0) + COALESCE(excesso, 0) + COALESCE(ordem, 0)\\n  ) AS `sum`\\nFROM\\n  `caracterizacao_escritura`\\nWHERE\\n  1 = 1\\n  [[AND `N√≠vel` = {{nivel}}]]\\n  [[AND `Professor(a)` = {{profesor}}]]\\n  [[AND ano_semestre = {{ano_semestre}}]]\\n  [[AND `Hor√°rio` = {{horario}}]]\\n  [[AND corte = {{corte}}]]\\n  [[AND email = {{Email}}]]\\nGROUP BY\\n  `Professor(a)`\\n\\nUNION ALL\\n\\n-- Total general\\nSELECT\\n  \'TOTAL\' AS `Professor`,\\n  SUM(\\n    COALESCE(ss, 0) + COALESCE(√ß, 0) + COALESCE(rr, 0) + COALESCE(x, 0) + COALESCE(s, 0) +\\n    COALESCE(acento_grave, 0) + COALESCE(acento_agudo, 0) + COALESCE(acento_circunflexo, 0) + COALESCE(til, 0) +\\n    COALESCE(verbos_regulares, 0) + COALESCE(verbos_irregulares, 0) +\\n    COALESCE(genero, 0) + COALESCE(numero, 0) +\\n    COALESCE(virgula, 0) + COALESCE(ponto_seguida, 0) + COALESCE(ponto_paragrafo, 0) + COALESCE(ponto_virgula, 0) +\\n    COALESCE(reticencias, 0) + COALESCE(ponto_interrogacao, 0) + COALESCE(ponto_exclamacao, 0) +\\n    COALESCE(travessao, 0) + COALESCE(aspas, 0) + COALESCE(parenteses, 0) +\\n    COALESCE(usualidade, 0) + COALESCE(portunhol, 0) + COALESCE(extra_terrestre, 0) +\\n    COALESCE(repeticoes_inadequadas, 0) + COALESCE(ausencia, 0) + COALESCE(excesso, 0) + COALESCE(ordem, 0)\\n  ) AS `sum`\\nFROM\\n  `caracterizacao_escritura`\\nWHERE\\n  1 = 1\\n  [[AND `N√≠vel` = {{nivel}}]]\\n  [[AND `Professor(a)` = {{profesor}}]]\\n  [[AND ano_semestre = {{ano_semestre}}]]\\n  [[AND `Hor√°rio` = {{horario}}]]\\n  [[AND corte = {{corte}}]]\\n  [[AND email = {{Email}}]]\\n\\nORDER BY\\n  CASE \\n    WHEN `Professor` = \'TOTAL\' THEN 1\\n    ELSE 0\\n  END,\\n  `Professor`;\\n\"},\"viz-settings\":{\"pie.rows\":[{\"key\":\"TOTAL\",\"name\":\"TOTAL\",\"originalName\":\"TOTAL\",\"color\":\"#F9D45C\",\"defaultColor\":true,\"enabled\":true,\"hidden\":false,\"isOther\":false},{\"key\":\"Antonio Lobato\",\"name\":\"Antonio Lobato\",\"originalName\":\"Antonio Lobato\",\"color\":\"#A7D07C\",\"defaultColor\":false,\"enabled\":true,\"hidden\":false,\"isOther\":false},{\"key\":\"Antonio Lino\",\"name\":\"Antonio Lino\",\"originalName\