ROM caracterizacao_escritura\\r\\n  WHERE 1=1\\r\\n    [[AND `N√≠vel` = {{nivel}}]] \\r\\n    [[AND `Professor(a)` = {{profesor}}]] \\r\\n    [[AND `Ano_Semestre` = {{ano_semestre}}]] \\r\\n    [[AND `Hor√°rio` = {{horario}}]] \\r\\n    [[AND `Corte` = {{corte}}]]\\r\\n    [[AND `Nome` = {{Nome}}]]\\r\\n\\r\\n  UNION ALL\\r\\n\\r\\n  -- CONC. VERBAL\\r\\n  SELECT \'CONC_VERBAL\', \\r\\n         SUM(verbos_regulares + verbos_irregulares)\\r\\n  FROM caracterizacao_escritura\\r\\n  WHERE 1=1\\r\\n    [[AND `N√≠vel` = {{nivel}}]] \\r\\n    [[AND `Professor(a)` = {{profesor}}]] \\r\\n    [[AND `Ano_Semestre` = {{ano_semestre}}]] \\r\\n    [[AND `Hor√°rio` = {{horario}}]] \\r\\n    [[AND `Corte` = {{corte}}]]\\r\\n    [[AND `Nome` = {{Nome}}]]\\r\\n\\r\\n  UNION ALL\\r\\n\\r\\n  -- CONC. NOMINAL\\r\\n  SELECT \'CONC_NOMINAL\', \\r\\n         SUM(genero + numero)\\r\\n  FROM caracterizacao_escritura\\r\\n  WHERE 1=1\\r\\n    [[AND `N√≠vel` = {{nivel}}]] \\r\\n    [[AND `Professor(a)` = {{profesor}}]] \\r\\n    [[AND `Ano_Semestre` = {{ano_semestre}}]] \\r\\n    [[AND `Hor√°rio` = {{horario}}]] \\r\\n    [[AND `Corte` = {{corte}}]]\\r\\n    [[AND `Nome` = {{Nome}}]]\\r\\n\\r\\n  UNION ALL\\r\\n\\r\\n  -- PUNTUACI√ìN\\r\\n  SELECT \'PONTUACAO\', \\r\\n         SUM(virgula + ponto_seguida + ponto_paragrafo + ponto_virgula + \\r\\n             reticencias + ponto_interrogacao + ponto_exclamacao + travessao + \\r\\n             aspas + parenteses)\\r\\n  FROM caracterizacao_escritura\\r\\n  WHERE 1=1\\r\\n    [[AND `N√≠vel` = {{nivel}}]] \\r\\n    [[AND `Professor(a)` = {{profesor}}]] \\r\\n    [[AND `Ano_Semestre` = {{ano_semestre}}]] \\r\\n    [[AND `Hor√°rio` = {{horario}}]] \\r\\n    [[AND `Corte` = {{corte}}]]\\r\\n    [[AND `Nome` = {{Nome}}]]\\r\\n\\r\\n  UNION ALL\\r\\n\\r\\n  -- VOCABULARIO\\r\\n  SELECT \'VOCABULARIO\', \\r\\n         SUM(usualidade + portunhol + extra_terrestre + repeticoes_inadequadas + \\r\\n             ausencia + excesso + ordem)\\r\\n  FROM caracterizacao_escritura\\r\\n  WHERE 1=1\\r\\n    [[AND `N√≠vel` = {{nivel}}]] \\r\\n    [[AND `Professor(a)` = {{profesor}}]] \\r\\n    [[AND `Ano_Semestre` = {{ano_semestre}}]] \\r\\n    [[AND `Hor√°rio` = {{horario}}]] \\r\\n    [[AND `Corte` = {{corte}}]]\\r\\n    [[AND `Nome` = {{Nome}}]]\\r\\n)\\r\\n\\r\\nSELECT \\r\\n  categoria,\\r\\n  total_erros,\\r\\n  ROUND((total_erros * 100.0) / NULLIF(SUM(total_erros) OVER (), 0), 2) AS porcentaje\\r\\nFROM errores_por_categoria\\r\\nORDER BY porcentaje DESC;\\r\\n\"},\"viz-settings\":{\"table.pivot_column\":\"categoria\",\"table.cell_column\":\"total_erros\",\"pivot_table.column_split\":{\"rows\":[\"total_erros\",\"porcentaje\"],\"columns\":[\"categoria\"],\"values\":[]},\"table.pivot\":false,\"table.columns\":[{\"name\":\"categoria\",\"enabled\":true},{\"name\":\"total_erros\",\"enabled\":true},{\"name\":\"porcentaje\",\"enabled\":true}],\"column_settings\":{\"[\\\"name\\\",\\\"porcentaje\\\"]\":{\"prefix\":\"\",\"show_mini_bar\":false,\"number_style\":\"decimal\",\"suffix\":\"%\"}}},\"database\":33,\"parameters\":[{\"type\":\"string/=\",\"value\":null,\"id\":\"b9da57ff\",\"target\":[\"variable\",[\"template-tag\",\"Nome\"]]}]}'),(_binary 'Ñ/é	Ö\Ûß{áy˚\‹n#:U}5]6\Œ\\\‘\Í{?Q]',71,'{\"constraints\":{\"max-results\":10000,\"max-results-bare-rows\":2000},\"type\":\"native\",\"middleware\":{\"js-int-to-string?\":true,\"ignore-cached-results?\":false,\"userland-query?\":true},\"cache-strategy\":null,\"native\":{\"template-tags\":{\"nivel\":{\"type\":\"text\",\"name\":\"nivel\",\"id\":\"24e6b10b-e736-4f1d-bb54-abdf1a7ae060\",\"display-name\":\"Nivel\"},\"ano_semestre\":{\"type\":\"text\",\"name\":\"ano_semestre\",\"id\":\"ce05b024-cdd9-4c95-b1af-ad7856874637\",\"display-name\":\"Ano Semestre\"},\"horario\":{\"type\":\"text\",\"name\":\"horario\",\"id\":\"5936287a-34ce-4e42-ab32-2784b81ab099\",\"display-name\":\"Horario\"},\"corte\":{\"type\":\"text\",\"name\":\"corte\",\"id\":\"69ff6817-f65b-43e8-99eb-47e11c40cd16\",\"dis