+ COALESCE(acento_circunflexo, 0) + COALESCE(til, 0)) AS total_errores\\nFROM caracterizacao_escritura\\nWHERE 1=1\\n  [[AND `N√≠vel` = {{nivel}}]]\\n  [[AND `Professor(a)` = {{profesor}}]]\\n  [[AND ano_semestre = {{ano_semestre}}]]\\n  [[AND `Hor√°rio` = {{horario}}]]\\n  [[AND corte = {{corte}}]]\\n  [[AND email = {{Email}}]]\\n\\nUNION ALL\\n\\n-- CONC_VERBAL por profesor\\nSELECT \'CONC_VERBAL\' AS categoria, \\n       `Professor(a)` AS Professor,\\n       SUM(COALESCE(verbos_regulares, 0) + COALESCE(verbos_irregulares, 0)) AS total_errores\\nFROM caracterizacao_escritura\\nWHERE 1=1\\n  [[AND `N√≠vel` = {{nivel}}]]\\n  [[AND `Professor(a)` = {{profesor}}]]\\n  [[AND ano_semestre = {{ano_semestre}}]]\\n  [[AND `Hor√°rio` = {{horario}}]]\\n  [[AND corte = {{corte}}]]\\n  [[AND email = {{Email}}]]\\nGROUP BY `Professor(a)`\\n\\nUNION ALL\\n\\n-- CONC_VERBAL total\\nSELECT \'CONC_VERBAL\' AS categoria, \\n       \'TOTAL\' AS Professor,\\n       SUM(COALESCE(verbos_regulares, 0) + COALESCE(verbos_irregulares, 0)) AS total_errores\\nFROM caracterizacao_escritura\\nWHERE 1=1\\n  [[AND `N√≠vel` = {{nivel}}]]\\n  [[AND `Professor(a)` = {{profesor}}]]\\n  [[AND ano_semestre = {{ano_semestre}}]]\\n  [[AND `Hor√°rio` = {{horario}}]]\\n  [[AND corte = {{corte}}]]\\n  [[AND email = {{Email}}]]\\n\\nUNION ALL\\n\\n-- CONC_NOMINAL por profesor\\nSELECT \'CONC_NOMINAL\' AS categoria, \\n       `Professor(a)` AS Professor,\\n       SUM(COALESCE(genero, 0) + COALESCE(numero, 0)) AS total_errores\\nFROM caracterizacao_escritura\\nWHERE 1=1\\n  [[AND `N√≠vel` = {{nivel}}]]\\n  [[AND `Professor(a)` = {{profesor}}]]\\n  [[AND ano_semestre = {{ano_semestre}}]]\\n  [[AND `Hor√°rio` = {{horario}}]]\\n  [[AND corte = {{corte}}]]\\n  [[AND email = {{Email}}]]\\nGROUP BY `Professor(a)`\\n\\nUNION ALL\\n\\n-- CONC_NOMINAL total\\nSELECT \'CONC_NOMINAL\' AS categoria, \\n       \'TOTAL\' AS Professor,\\n       SUM(COALESCE(genero, 0) + COALESCE(numero, 0)) AS total_errores\\nFROM caracterizacao_escritura\\nWHERE 1=1\\n  [[AND `N√≠vel` = {{nivel}}]]\\n  [[AND `Professor(a)` = {{profesor}}]]\\n  [[AND ano_semestre = {{ano_semestre}}]]\\n  [[AND `Hor√°rio` = {{horario}}]]\\n  [[AND corte = {{corte}}]]\\n  [[AND email = {{Email}}]]\\n\\nUNION ALL\\n\\n-- PONTUACAO por profesor\\nSELECT \'PONTUACAO\' AS categoria, \\n       `Professor(a)` AS Professor,\\n       SUM(COALESCE(virgula, 0) + COALESCE(ponto_seguida, 0) + COALESCE(ponto_paragrafo, 0) + COALESCE(ponto_virgula, 0) +\\n           COALESCE(reticencias, 0) + COALESCE(ponto_interrogacao, 0) + COALESCE(ponto_exclamacao, 0) +\\n           COALESCE(travessao, 0) + COALESCE(aspas, 0) + COALESCE(parenteses, 0)) AS total_errores\\nFROM caracterizacao_escritura\\nWHERE 1=1\\n  [[AND `N√≠vel` = {{nivel}}]]\\n  [[AND `Professor(a)` = {{profesor}}]]\\n  [[AND ano_semestre = {{ano_semestre}}]]\\n  [[AND `Hor√°rio` = {{horario}}]]\\n  [[AND corte = {{corte}}]]\\n  [[AND email = {{Email}}]]\\nGROUP BY `Professor(a)`\\n\\nUNION ALL\\n\\n-- PONTUACAO total\\nSELECT \'PONTUACAO\' AS categoria, \\n       \'TOTAL\' AS Professor,\\n       SUM(COALESCE(virgula, 0) + COALESCE(ponto_seguida, 0) + COALESCE(ponto_paragrafo, 0) + COALESCE(ponto_virgula, 0) +\\n           COALESCE(reticencias, 0) + COALESCE(ponto_interrogacao, 0) + COALESCE(ponto_exclamacao, 0) +\\n           COALESCE(travessao, 0) + COALESCE(aspas, 0) + COALESCE(parenteses, 0)) AS total_errores\\nFROM caracterizacao_escritura\\nWHERE 1=1\\n  [[AND `N√≠vel` = {{nivel}}]]\\n  [[AND `Professor(a)` = {{profesor}}]]\\n  [[AND ano_semestre = {{ano_semestre}}]]\\n  [[AND `Hor√°rio` = {{horario}}]]\\n  [[AND corte = {{corte}}]]\\n  [[AND email = {{Email}}]]\\n\\nUNION ALL\\n\\n-- VOCABULARIO por profesor\\nSELECT \'VOCABULARIO\' AS categoria, \\n       `Professor(a)` AS Professor,\\n       SUM(COALESCE(usualidade, 0) + COALESCE(portunhol, 0) + COALESCE(extra_terrestre, 0) +\\n           COALESCE(repeticoes_inadequadas, 0) + COALESCE(ausencia, 0) + COALESCE(excesso, 0