ring?\":true,\"ignore-cached-results?\":false,\"userland-query?\":true},\"cache-strategy\":null,\"native\":{\"template-tags\":{\"nivel\":{\"type\":\"text\",\"name\":\"nivel\",\"id\":\"3b5b6680-e828-4ccc-9a09-25bbc7d590d9\",\"display-name\":\"Nivel\"},\"profesor\":{\"type\":\"text\",\"name\":\"profesor\",\"id\":\"12a94bee-44de-4f89-b773-407494c8918e\",\"display-name\":\"Profesor\"},\"ano_semestre\":{\"type\":\"text\",\"name\":\"ano_semestre\",\"id\":\"bcde2905-755a-4a5c-84c2-441c28744ada\",\"display-name\":\"Ano Semestre\"},\"horario\":{\"type\":\"text\",\"name\":\"horario\",\"id\":\"086b1260-1422-42d2-a308-3cbc05870e10\",\"display-name\":\"Horario\"},\"corte\":{\"type\":\"text\",\"name\":\"corte\",\"id\":\"f43b07e6-d2cd-4111-aa65-7efbda7090eb\",\"display-name\":\"Corte\"},\"Email\":{\"type\":\"text\",\"name\":\"Email\",\"id\":\"020395e6-6711-4393-b787-917bea885c64\",\"display-name\":\"Email\"}},\"query\":\"WITH promedio_por_profesor AS (\\n  SELECT\\n    `Professor(a)` AS Professor,\\n    SUM(\\n      COALESCE(`ss`, 0) + COALESCE(`√ß`, 0) + COALESCE(`rr`, 0) + COALESCE(`x`, 0) + COALESCE(`s`, 0) +\\n      COALESCE(`acento_grave`, 0) + COALESCE(`acento_agudo`, 0) + COALESCE(`acento_circunflexo`, 0) + COALESCE(`til`, 0) +\\n      COALESCE(`verbos_regulares`, 0) + COALESCE(`verbos_irregulares`, 0) +\\n      COALESCE(`genero`, 0) + COALESCE(`numero`, 0) +\\n      COALESCE(`virgula`, 0) + COALESCE(`ponto_seguida`, 0) + COALESCE(`ponto_paragrafo`, 0) + COALESCE(`ponto_virgula`, 0) +\\n      COALESCE(`reticencias`, 0) + COALESCE(`ponto_interrogacao`, 0) + COALESCE(`ponto_exclamacao`, 0) +\\n      COALESCE(`travessao`, 0) + COALESCE(`aspas`, 0) + COALESCE(`parenteses`, 0) +\\n      COALESCE(`usualidade`, 0) + COALESCE(`portunhol`, 0) + COALESCE(`extra_terrestre`, 0) +\\n      COALESCE(`repeticoes_inadequadas`, 0) + COALESCE(`ausencia`, 0) + COALESCE(`excesso`, 0) + COALESCE(`ordem`, 0)\\n    ) / COUNT(*) AS promedio_errores\\n  FROM `caracterizacao_escritura`\\n  WHERE 1=1\\n    [[AND `N√≠vel` = {{nivel}}]]\\n    [[AND `Professor(a)` = {{profesor}}]]\\n    [[AND ano_semestre = {{ano_semestre}}]]\\n    [[AND `Hor√°rio` = {{horario}}]]\\n    [[AND corte = {{corte}}]]\\n    [[AND email = {{Email}}]]\\n  GROUP BY `Professor(a)`\\n),\\n\\n-- CTE para calcular total general\\ntotal_general AS (\\n  SELECT\\n    \'Total general\' AS Professor,\\n    SUM(\\n      COALESCE(`ss`, 0) + COALESCE(`√ß`, 0) + COALESCE(`rr`, 0) + COALESCE(`x`, 0) + COALESCE(`s`, 0) +\\n      COALESCE(`acento_grave`, 0) + COALESCE(`acento_agudo`, 0) + COALESCE(`acento_circunflexo`, 0) + COALESCE(`til`, 0) +\\n      COALESCE(`verbos_regulares`, 0) + COALESCE(`verbos_irregulares`, 0) +\\n      COALESCE(`genero`, 0) + COALESCE(`numero`, 0) +\\n      COALESCE(`virgula`, 0) + COALESCE(`ponto_seguida`, 0) + COALESCE(`ponto_paragrafo`, 0) + COALESCE(`ponto_virgula`, 0) +\\n      COALESCE(`reticencias`, 0) + COALESCE(`ponto_interrogacao`, 0) + COALESCE(`ponto_exclamacao`, 0) +\\n      COALESCE(`travessao`, 0) + COALESCE(`aspas`, 0) + COALESCE(`parenteses`, 0) +\\n      COALESCE(`usualidade`, 0) + COALESCE(`portunhol`, 0) + COALESCE(`extra_terrestre`, 0) +\\n      COALESCE(`repeticoes_inadequadas`, 0) + COALESCE(`ausencia`, 0) + COALESCE(`excesso`, 0) + COALESCE(`ordem`, 0)\\n    ) / COUNT(*) AS promedio_errores\\n  FROM `caracterizacao_escritura`\\n  WHERE 1=1\\n    [[AND `N√≠vel` = {{nivel}}]]\\n    [[AND `Professor(a)` = {{profesor}}]]\\n    [[AND ano_semestre = {{ano_semestre}}]]\\n    [[AND `Hor√°rio` = {{horario}}]]\\n    [[AND corte = {{corte}}]]\\n    [[AND email = {{Email}}]]\\n)\\n\\n-- Unimos ambos resultados\\nSELECT * FROM promedio_por_profesor\\nUNION ALL\\nSELECT * FROM total_general\\nORDER BY\\n  CASE \\n    WHEN Professor = \'Total general\' THEN 1\\n    ELSE 0\\n  END,\\n  Professor;\"},\"viz-settings\":{\"graph.series_order\":null,\"graph.series_order_dimension\":null,\"graph.label_value_formatting\":\"compact\",\"graph.dimensions\":[\"Professor\",\"promedio_errores\"],\"series_settings\":{\"19\":{\"color\":\"#999AC4\"},\"promedio_errores\":{\"color\":\"#A7D07C\"},\"total_general\":{\"color\":\"#F9D45C\"},\"23.57\":{\"color\":\"#F9D45C\"},\"23.63\":{\"color\":\"#A7D07C\"}},\"graph.show_values\":true,\"graph.metrics\":[\"promedio_errores\"]},\"database\":33,\"parameters\":[{\"type\":\"string/=\",\"value\":null,\"id\":\"a31eb0c9\",\"target\":[\"variable\",[\"template-tag\",\"nivel\"]]},{\"type\":\"string/=\",\"value\":null,\"id\":\"3cd8e1bf\",\"target\":[\"variable\",[\"template-tag\",\"ano_semestre\"]]},{\"type\":\"string/=\",\"value\":null,\"id\":\"71a84056\",\"target\":[\"variable\",[\"template-tag\",\"horario\"]]},{\"type\":\"string/=\",\"value\":null,\"id\":\"a6a24ed\",\"target\":[\"variable\",[\"template-tag\",\"profesor\"]]},{\"type\":\"string/=\",\"value\":null,\"id\":\"d487f1eb\",\"target\":[\"variable\",[\"template-tag\",\"corte\"]]}]}'),(_binary '£∂˚Ñ(≠u\ır0J55enÅëR\ˆ-¡ãwI7Ü~#Ü\\',28,'{\"constraints\":{\"max-results\":10000,\"max-results-bare-rows\":2000},\"type\":\"native\",\"middleware\":{\"js-int-to-string?\":true,\"ignore-cached-results?\":false,\"process-viz-settings?\":false,\"userland-query?\":true},\"cache-strategy\":null,\"native\":{\"template-tags\":{\"nivel\":{\"type\":\"text\",\"name\":\"nivel\",\"id\":\"56b70b29-841e-4407-ab18-4dfaff8a7ed1\",\"display-name\":\"Nivel\"},\"profesor\":{\"type\":\"text\",\"name\":\"profesor\",\"id\":\"5e09c7de-1a7b-463e-97b4-3c40fe6cbf45\",\"display-name\":\"Profesor\"},\"ano_semestre\":{\"type\":\"text\",\"name\":\"ano_semestre\",\"id\":\"3a5f6f8e-2e9b-40ce-857a-99107cf5b6b5\",\"display-name\":\"Ano Semestre\"},\"horario\":{\"type\":\"text\",\"name\":\"horario\",\"id\":\"32667b0c-0023-4fa3-8a33-18f58c66c76f\",\"display-name\":\"Horario\"},\"corte\":{\"type\":\"text\",\"name\":\"corte\",\"id\":\"46465323-87fa-4542-9d30-9049fd50b28d\",\"display-name\":\"Corte\"},\"Nome\":{\"type\":\"text\",\"name\":\"Nome\",\"id\":\"59193605-f05c-44a5-bcb7-a8085c119e42\",\"display-n