-tags\":{\"nivel\":{\"type\":\"text\",\"name\":\"nivel\",\"id\":\"f9dc635f-13e5-4438-8e00-9825faad0f11\",\"display-name\":\"Nivel\"},\"profesor\":{\"type\":\"text\",\"name\":\"profesor\",\"id\":\"6f3c639d-2247-4429-b45e-a4a56c5ceb85\",\"display-name\":\"Profesor\"},\"ano_semestre\":{\"type\":\"text\",\"name\":\"ano_semestre\",\"id\":\"09f2739f-aa11-4699-bf51-fd47b4870517\",\"display-name\":\"Ano Semestre\"},\"horario\":{\"type\":\"text\",\"name\":\"horario\",\"id\":\"72e2ef52-73c9-4629-95ea-a0722c2b075b\",\"display-name\":\"Horario\"},\"corte\":{\"type\":\"text\",\"name\":\"corte\",\"id\":\"7ef1a57b-919a-4650-b0bf-c5f865e275f0\",\"display-name\":\"Corte\"},\"Nome\":{\"type\":\"text\",\"name\":\"Nome\",\"id\":\"e90db8c5-8824-41e4-8bc3-1ccf1838c7c5\",\"display-name\":\"Nome\"},\"Email\":{\"type\":\"text\",\"name\":\"Email\",\"id\":\"f2dd79a2-34cd-4ad6-955c-183874cffb75\",\"display-name\":\"Email\"}},\"query\":\"WITH errores_por_categoria AS (\\n  -- ORTOGRAF√çA\\n  SELECT \'ORTOGRAF\' AS categoria, \\n         SUM(COALESCE(ss, 0) + COALESCE(√ß, 0) + COALESCE(rr, 0) + COALESCE(x, 0) + COALESCE(s, 0)) AS total_erros,\\n         MAX(email) AS email\\n  FROM caracterizacao_escritura\\n  WHERE 1=1\\n    [[AND `N√≠vel` = {{nivel}}]] \\n    [[AND `Professor(a)` = {{profesor}}]] \\n    [[AND ano_semestre = {{ano_semestre}}]] \\n    [[AND `Hor√°rio` = {{horario}}]] \\n    [[AND corte = {{corte}}]]\\n    [[AND `Nome` = {{Nome}}]]\\n    [[AND email = {{Email}}]]\\n\\n  UNION ALL\\n\\n  -- ACENTUACI√ìN\\n  SELECT \'ACENTUAC\' AS categoria, \\n         SUM(COALESCE(acento_grave, 0) + COALESCE(acento_agudo, 0) + COALESCE(acento_circunflexo, 0) + COALESCE(til, 0)) AS total_erros,\\n         MAX(email) AS email\\n  FROM caracterizacao_escritura\\n  WHERE 1=1\\n    [[AND `N√≠vel` = {{nivel}}]] \\n    [[AND `Professor(a)` = {{profesor}}]] \\n    [[AND ano_semestre = {{ano_semestre}}]] \\n    [[AND `Hor√°rio` = {{horario}}]] \\n    [[AND corte = {{corte}}]]\\n    [[AND `Nome` = {{Nome}}]]\\n    [[AND email = {{Email}}]]\\n\\n  UNION ALL\\n\\n  -- CONC. VERBAL\\n  SELECT \'CONC_VERBAL\' AS categoria, \\n         SUM(COALESCE(verbos_regulares, 0) + COALESCE(verbos_irregulares, 0)) AS total_erros,\\n         MAX(email) AS email\\n  FROM caracterizacao_escritura\\n  WHERE 1=1\\n    [[AND `N√≠vel` = {{nivel}}]] \\n    [[AND `Professor(a)` = {{profesor}}]] \\n    [[AND ano_semestre = {{ano_semestre}}]] \\n    [[AND `Hor√°rio` = {{horario}}]] \\n    [[AND corte = {{corte}}]]\\n    [[AND `Nome` = {{Nome}}]]\\n    [[AND email = {{Email}}]]\\n\\n  UNION ALL\\n\\n  -- CONC. NOMINAL\\n  SELECT \'CONC_NOMINAL\' AS categoria, \\n         SUM(COALESCE(genero, 0) + COALESCE(numero, 0)) AS total_erros,\\n         MAX(email) AS email\\n  FROM caracterizacao_escritura\\n  WHERE 1=1\\n    [[AND `N√≠vel` = {{nivel}}]] \\n    [[AND `Professor(a)` = {{profesor}}]] \\n    [[AND ano_semestre = {{ano_semestre}}]] \\n    [[AND `Hor√°rio` = {{horario}}]] \\n    [[AND corte = {{corte}}]]\\n    [[AND `Nome` = {{Nome}}]]\\n    [[AND email = {{Email}}]]\\n\\n  UNION ALL\\n\\n  -- PUNTUACI√ìN\\n  SELECT \'PONTUACAO\' AS categoria, \\n         SUM(COALESCE(virgula, 0) + COALESCE(ponto_seguida, 0) + COALESCE(ponto_paragrafo, 0) + COALESCE(ponto_virgula, 0) + \\n             COALESCE(reticencias, 0) + COALESCE(ponto_interrogacao, 0) + COALESCE(ponto_exclamacao, 0) + COALESCE(travessao, 0) + \\n             COALESCE(aspas, 0) + COALESCE(parenteses, 0)) AS total_erros,\\n         MAX(email) AS email\\n  FROM caracterizacao_escritura\\n  WHERE 1=1\\n    [[AND `N√≠vel` = {{nivel}}]] \\n    [[AND `Professor(a)` = {{profesor}}]] \\n    [[AND ano_semestre = {{ano_semestre}}]] \\n    [[AND `Hor√°rio` = {{horario}}]] \\n    [[AND corte = {{corte}}]]\\n    [[AND `Nome` = {{Nome}}]]\\n    [[AND email = {{Email}}]]\\n\\n  UNION ALL\\n\\n  -- VOCABULARIO\\n  SELECT \'VOCABULARIO\' AS categoria, \\n         SUM(COALESCE(usualidade, 0) + COALESCE(portunhol, 0) + COALESCE(extra_terrestre, 0) + COALESCE(repeticoes_inadequadas, 0) + \\n             COALESCE(ausencia, 0) + COALESCE(excesso, 0) + COALESCE(ordem, 0)) AS total_erros,\\n         MAX(email) AS email\\n  FROM caracterizacao_escritura\\n  WHERE 1=1\\n    [[AND `N√≠vel` = {{nivel}}]] \\n    [[AND `Professor(a)` = {{profesor}}]] \\n    [[AND ano_semestre = {{ano_semestre}}]] \\n    [[AND `Hor√°rio` = {{horario}}]] \\n    [[AND corte = {{corte}}]]\\n    [[AND `Nome` = {{Nome}}]]\\n    [[AND email = {{Email}}]]\\n)\\n\\nSELECT \\n  categoria,\\n  total_erros,\\n  ROUND((total_erros * 100.0) / NULLIF(SUM(total_erros) OVER (), 0), 2) AS porcentaje,\\n  email\\nFROM errores_por_categoria\\nWHERE total_erros > 0\\nORDER BY total_erros DESC;\"},\"parameters\":[{\"id\":\"f9dc635f-13e5-4438-8e00-9825faad0f11\",\"type\":\"category\",\"value\":null,\"target\":[\"variable\",[\"template-tag\",\"nivel\"]]},{\"id\":\"6f3c639d-2247-4429-b45e-a4a56c5ceb85\",\"type\":\"category\",\"value\":null,\"target\":[\"variable\",[\"template-tag\",\"profesor\"]]},{\"id\":\"09f2739f-aa11-4699-bf51-fd47b4870517\",\"type\":\"category\",\"value\":null,\"target\":[\"variable\",[\"template-tag\",\"ano_semestre\"]]},{\"id\":\"72e2ef52-73c9-4629-95ea-a0722c2b075b\",\"type\":\"category\",\"value\":null,\"target\":[\"variable\",[\"template-tag\",\"horario\"]]},{\"id\":\"7ef1a57b-919a-4650-b0bf-c5f865e275f0\",\"type\":\"category\",\"value\":null,\"target\":[\"variable\",[\"template-tag\",\"corte\"]]},{\"id\":\"e90db8c5-8824-41e4-8bc3-1ccf1838c7c5\",\"type\":\"category\",\"value\":null,\"target\":[\"variable\",[\"template-tag\",\"Nome\"]]},{\"id\":\"f2dd79a2-34cd-4ad6-955c-183874cffb75\",\"type\":\"category\",\"value\":null,\"target\":[\"variable\",[\"template-tag\",\"Email\"]]}],\"middleware\":{\"js-int-to-string?\":true,\"userland-query?\":true,\"add-default-userland-constraints?\":true}}'),(_binary '\Î&\Û\◊\‰wd1\»\ıG\€\¬\ÿO\\Ì}\¬¿yEÉ\\,\0à[/-',37,'{\"constraints\":{\"max-results\":10000,\"max-results-bare-rows\":2000},\"type\":\"native\",