INSERT INTO `report_card` VALUES (1,'2025-03-19 16:31:35.735486','2025-03-19 16:31:35.735486','Orders + People','Sample orders joined with products','table','{\"database\":1,\"query\":{\"expressions\":{\"Age\":[\"datetime-diff\",[\"field\",12,{\"base-type\":\"type/Date\",\"join-alias\":\"People - User\"}],[\"now\"],\"year\"]},\"joins\":[{\"alias\":\"People - User\",\"condition\":[\"=\",[\"field\",11,{\"base-type\":\"type/Integer\"}],[\"field\",4,{\"base-type\":\"type/BigInteger\",\"join-alias\":\"People - User\"}]],\"fields\":[[\"field\",7,{\"base-type\":\"type/Text\",\"join-alias\":\"People - User\"}],[\"field\",1,{\"base-type\":\"type/Text\",\"join-alias\":\"People - User\"}]],\"source-table\":1,\"strategy\":\"left-join\"}],\"source-table\":2},\"type\":\"query\"}','{\"column_settings\":null,\"table.cell_column\":\"SUBTOTAL\",\"table.columns\":[{\"enabled\":true,\"name\":\"ID\"},{\"enabled\":true,\"name\":\"USER_ID\"},{\"enabled\":true,\"name\":\"PRODUCT_ID\"},{\"enabled\":true,\"name\":\"SUBTOTAL\"},{\"enabled\":true,\"name\":\"TAX\"},{\"enabled\":true,\"name\":\"TOTAL\"},{\"enabled\":true,\"name\":\"DISCOUNT\"},{\"enabled\":true,\"name\":\"CREATED_AT\"},{\"enabled\":true,\"name\":\"QUANTITY\"},{\"enabled\":true,\"name\":\"EMAIL\"},{\"enabled\":true,\"name\":\"Age\"},{\"enabled\":true,\"name\":\"STATE\"}],\"table.pivot_column\":\"SOURCE\"}',13371338,1,2,'query',_binary '\0',2,NULL,NULL,_binary '\0',NULL,NULL,'[{\"base_type\":\"type/BigInteger\",\"coercion_strategy\":null,\"description\":\"This is a unique ID for the product. It is also called the ‚ÄúInvoice number‚Äù or ‚ÄúConfirmation number‚Äù in customer facing emails and screens.\",\"display_name\":\"ID\",\"effective_type\":\"type/BigInteger\",\"field_ref\":[\"field\",9,null],\"fk_target_field_id\":null,\"id\":9,\"name\":\"ID\",\"semantic_type\":\"type/PK\",\"settings\":null,\"visibility_type\":\"normal\"},{\"base_type\":\"type/Integer\",\"coercion_strategy\":null,\"description\":\"The id of the user who made 