 = {{horario}}]]\\n  [[AND corte = {{corte}}]]\\n  [[AND email = {{Email}}]]\\nGROUP BY `Hor√°rio`\\n\\nUNION ALL\\n\\nSELECT \'CONC_NOMINAL\' AS categoria, \\n       `Hor√°rio` AS horario,\\n       SUM(COALESCE(genero, 0) + COALESCE(numero, 0)) AS total_errores\\nFROM caracterizacao_escritura\\nWHERE 1=1\\n  [[AND `N√≠vel` = {{nivel}}]]\\n  [[AND `Professor(a)` = {{profesor}}]]\\n  [[AND ano_semestre = {{ano_semestre}}]]\\n  [[AND `Hor√°rio` = {{horario}}]]\\n  [[AND corte = {{corte}}]]\\n  [[AND email = {{Email}}]]\\nGROUP BY `Hor√°rio`\\n\\nUNION ALL\\n\\nSELECT \'PONTUACAO\' AS categoria, \\n       `Hor√°rio` AS horario,\\n       SUM(COALESCE(virgula, 0) + COALESCE(ponto_seguida, 0) + COALESCE(ponto_paragrafo, 0) + COALESCE(ponto_virgula, 0) +\\n           COALESCE(reticencias, 0) + COALESCE(ponto_interrogacao, 0) + COALESCE(ponto_exclamacao, 0) +\\n           COALESCE(travessao, 0) + COALESCE(aspas, 0) + COALESCE(parenteses, 0)) AS total_errores\\nFROM caracterizacao_escritura\\nWHERE 1=1\\n  [[AND `N√≠vel` = {{nivel}}]]\\n  [[AND `Professor(a)` = {{profesor}}]]\\n  [[AND ano_semestre = {{ano_semestre}}]]\\n  [[AND `Hor√°rio` = {{horario}}]]\\n  [[AND corte = {{corte}}]]\\n  [[AND email = {{Email}}]]\\nGROUP BY `Hor√°rio`\\n\\nUNION ALL\\n\\nSELECT \'VOCABULARIO\' AS categoria, \\n       `Hor√°rio` AS horario,\\n       SUM(COALESCE(usualidade, 0) + COALESCE(portunhol, 0) + COALESCE(extra_terrestre, 0) +\\n           COALESCE(repeticoes_inadequadas, 0) + COALESCE(ausencia, 0) + COALESCE(excesso, 0) + COALESCE(ordem, 0)) AS total_errores\\nFROM caracterizacao_escritura\\nWHERE 1=1\\n  [[AND `N√≠vel` = {{nivel}}]]\\n  [[AND `Professor(a)` = {{profesor}}]]\\n  [[AND ano_semestre = {{ano_semestre}}]]\\n  [[AND `Hor√°rio` = {{horario}}]]\\n  [[AND corte = {{corte}}]]\\n  [[AND email = {{Email}}]]\\nGROUP BY `Hor√°rio`;\"}}','{\"graph.dimensions\":[\"categoria\",\"horario\"],\"graph.show_values\":true,\"graph.metrics\":[\"total_errores\"],\"graph.x_axis.scale\":\"ordi