 COALESCE(`extra_terrestre`, 0) +\\n      COALESCE(`repeticoes_inadequadas`, 0) + COALESCE(`ausencia`, 0) + COALESCE(`excesso`, 0) + COALESCE(`ordem`, 0)\\n    ) / COUNT(*) AS promedio_errores\\n  FROM `caracterizacao_escritura`\\n  WHERE 1=1\\n    [[AND `N√≠vel` = {{nivel}}]]\\n    [[AND `Professor(a)` = {{profesor}}]]\\n    [[AND ano_semestre = {{ano_semestre}}]]\\n    [[AND `Hor√°rio` = {{horario}}]]\\n    [[AND corte = {{corte}}]]\\n    [[AND email = {{Email}}]]\\n  GROUP BY `Professor(a)`\\n),\\n\\n-- CTE para calcular total general\\ntotal_general AS (\\n  SELECT\\n    \'Total general\' AS Professor,\\n    SUM(\\n      COALESCE(`ss`, 0) + COALESCE(`√ß`, 0) + COALESCE(`rr`, 0) + COALESCE(`x`, 0) + COALESCE(`s`, 0) +\\n      COALESCE(`acento_grave`, 0) + COALESCE(`acento_agudo`, 0) + COALESCE(`acento_circunflexo`, 0) + COALESCE(`til`, 0) +\\n      COALESCE(`verbos_regulares`, 0) + COALESCE(`verbos_irregulares`, 0) +\\n      COALESCE(`genero`, 0) + COALESCE(`numero`, 0) +\\n      COALESCE(`virgula`, 0) + COALESCE(`ponto_seguida`, 0) + COALESCE(`ponto_paragrafo`, 0) + COALESCE(`ponto_virgula`, 0) +\\n      COALESCE(`reticencias`, 0) + COALESCE(`ponto_interrogacao`, 0) + COALESCE(`ponto_exclamacao`, 0) +\\n      COALESCE(`travessao`, 0) + COALESCE(`aspas`, 0) + COALESCE(`parenteses`, 0) +\\n      COALESCE(`usualidade`, 0) + COALESCE(`portunhol`, 0) + COALESCE(`extra_terrestre`, 0) +\\n      COALESCE(`repeticoes_inadequadas`, 0) + COALESCE(`ausencia`, 0) + COALESCE(`excesso`, 0) + COALESCE(`ordem`, 0)\\n    ) / COUNT(*) AS promedio_errores\\n  FROM `caracterizacao_escritura`\\n  WHERE 1=1\\n    [[AND `N√≠vel` = {{nivel}}]]\\n    [[AND `Professor(a)` = {{profesor}}]]\\n    [[AND ano_semestre = {{ano_semestre}}]]\\n    [[AND `Hor√°rio` = {{horario}}]]\\n    [[AND corte = {{corte}}]]\\n    [[AND email = {{Email}}]]\\n)\\n\\n-- Unimos ambos resultados\\nSELECT * FROM promedio_por_profesor\\nUNION ALL\\nSELECT * FROM total_general\\nORDER BY\\n  CASE \\n    WHEN Professor = \'Total general\' THEN 1\\n    ELSE 0\\n  END,\\n  Professor;\"}}','{\"graph.series_order\":null,\"graph.series_order_dimension\":null,\"graph.label_value_formatting\":\"compact\",\"graph.dimensions\":[\"Professor\",\"promedio_errores\"],\"series_settings\":{\"19\":{\"color\":\"#999AC4\"},\"promedio_errores\":{\"color\":\"#A7D07C\"},\"total_general\":{\"color\":\"#F9D45C\"},\"23.57\":{\"color\":\"#F9D45C\"},\"23.63\":{\"color\":\"#A7D07C\"}},\"graph.show_values\":true,\"graph.metrics\":[\"promedio_errores\"]}',1,33,NULL,'native',_binary '\0',10,NULL,NULL,_binary '\0',NULL,NULL,'[{\"display_name\":\"Professor\",\"field_ref\":[\"field\",\"Professor\",{\"base-type\":\"type/Text\"}],\"base_type\":\"type/Text\",\"effective_type\":\"type/Text\",\"database_type\":\"VARCHAR\",\"name\":\"Professor\",\"semantic_type\":null,\"fingerprint\":{\"global\":{\"distinct-count\":3,\"nil%\":0.0},\"type\":{\"type/Text\":{\"percent-json\":0.0,\"percent-url\":0.0,\"percent-email\":0.0,\"percent-state\":0.0,\"average-length\":13.0}}}},{\"display_name\":\"promedio_errores\",\"field_ref\":[\"field\",\"promedio_errores\",{\"base-type\":\"type/Decimal\"}],\"base_type\":\"type/Decimal\",\"effective_type\":\"type/Decimal\",\"database_type\":\"DECIMAL\",\"name\":\"promedio_errores\",\"semantic_type\":null,\"fingerprint\":{\"global\":{\"distinct-count\":3,\"nil%\":0.0},\"type\":{\"type/Number\":{\"min\":19.0,\"q1\":20.14235,\"q3\":23.6177,\"max\":23.6338,\"sd\":2.65693012579054,\"avg\":22.067733333333337}}}}]',NULL,'-UYYz2rlhxuXI8yW2nI6e','[{\"id\":\"3b5b6680-e828-4ccc-9a09-25bbc7d590d9\",\"type\":\"category\",\"target\":[\"variable\",[\"template-tag\",\"nivel\"]],\"name\":\"Nivel\",\"slug\":\"nivel\"},{\"id\":\"12a94bee-44de-4f89-b773-407494c8918e\",\"type\":\"category\",\"target\":[\"variable\",[\"template-tag\",\"profesor\"]],\"name\":\"Profesor\",\"slug\":\"profesor\"},{\"id\":\"bcde2905-755a-4a5c-84c2-441c28744ada\",\"type\":\"category\",\"target\":[\"variable\",[\"template-tag\",\"ano_se