+ ponto_exclamacao + travessao + \\n           aspas + parenteses)\\nFROM caracterizacao_escritura\\nWHERE 1=1\\n  [[AND `N√≠vel` = {{nivel}}]] \\n  [[AND `Professor(a)` = {{profesor}}]] \\n  [[AND `Ano_Semestre` = {{ano_semestre}}]] \\n  [[AND `Hor√°rio` = {{horario}}]] \\n  [[AND `Corte` = {{corte}}]]\\n  [[AND `Nome` = {{Nome}}]]\\n      [[AND email = {{Email}}]]\\n\\n\\nUNION ALL\\n\\n-- VOCABULARIO\\nSELECT \'VOCABULARIO\', \\n       SUM(usualidade + portunhol + extra_terrestre + repeticoes_inadequadas + \\n           ausencia + excesso + ordem)\\nFROM caracterizacao_escritura\\nWHERE 1=1\\n  [[AND `N√≠vel` = {{nivel}}]] \\n  [[AND `Professor(a)` = {{profesor}}]] \\n  [[AND `Ano_Semestre` = {{ano_semestre}}]] \\n  [[AND `Hor√°rio` = {{horario}}]] \\n  [[AND `Corte` = {{corte}}]]\\n  [[AND `Nome` = {{Nome}}]]\\n      [[AND email = {{Email}}]]\\n\"}}','{\"graph.dimensions\":[\"categoria\"],\"graph.show_values\":true,\"graph.x_axis.title_text\":\"CATEGORIA\",\"graph.metrics\":[\"total_erros\"],\"graph.x_axis.scale\":\"ordinal\"}',1,33,NULL,'native',_binary '\0',10,NULL,NULL,_binary '\0',NULL,NULL,'[{\"display_name\":\"categoria\",\"field_ref\":[\"field\",\"categoria\",{\"base-type\":\"type/Text\"}],\"base_type\":\"type/Text\",\"effective_type\":\"type/Text\",\"database_type\":\"VARCHAR\",\"name\":\"categoria\",\"semantic_type\":null,\"fingerprint\":{\"global\":{\"distinct-count\":6,\"nil%\":0.0},\"type\":{\"type/Text\":{\"percent-json\":0.0,\"percent-url\":0.0,\"percent-email\":0.0,\"percent-state\":0.0,\"average-length\":9.833333333333334}}}},{\"display_name\":\"total_erros\",\"field_ref\":[\"field\",\"total_erros\",{\"base-type\":\"type/Decimal\"}],\"base_type\":\"type/Decimal\",\"effective_type\":\"type/Decimal\",\"database_type\":\"DECIMAL\",\"name\":\"total_erros\",\"semantic_type\":null,\"fingerprint\":{\"global\":{\"distinct-count\":6,\"nil%\":0.0},\"type\":{\"type/Number\":{\"min\":85.0,\"q1\":162.0,\"q3\":398.0,\"max\":562.0,\"sd\":173.96944176109398,\"avg\":282.8333333333333}}}}]',NULL,'q4u3ZSrr-kv6vwOCFFnrb','[{\"id\":\"e03c1a21-7ca2-4f66-933c-d844f0e9cbbd\",\"type\":\"category\",\"target\":[\"variable\",[\"template-tag\",\"nivel\"]],\"name\":\"Nivel\",\"slug\":\"nivel\"},{\"id\":\"c779d0ce-0dce-4c00-9fd0-7341c8f9d41b\",\"type\":\"category\",\"target\":[\"variable\",[\"template-tag\",\"profesor\"]],\"name\":\"Profesor\",\"slug\":\"profesor\"},{\"id\":\"1f3488eb-a740-456c-8d4e-b43151c942f2\",\"type\":\"category\",\"target\":[\"variable\",[\"template-tag\",\"ano_semestre\"]],\"name\":\"Ano Semestre\",\"slug\":\"ano_semestre\"},{\"id\":\"ec5445a9-48e0-4d4f-8972-11034593c725\",\"type\":\"category\",\"target\":[\"variable\",[\"template-tag\",\"horario\"]],\"name\":\"Horario\",\"slug\":\"horario\"},{\"id\":\"f2b61f39-273d-40a2-bae8-2855876e61e2\",\"type\":\"category\",\"target\":[\"variable\",[\"template-tag\",\"corte\"]],\"name\":\"Corte\",\"slug\":\"corte\"},{\"id\":\"a185d68f-4d3f-41bc-abcf-a61c8b65af38\",\"type\":\"category\",\"target\":[\"variable\",[\"template-tag\",\"Nome\"]],\"name\":\"Nome\",\"slug\":\"Nome\"},{\"id\":\"92b0d7bf-e31d-47bc-929a-4aff995b5d58\",\"type\":\"category\",\"target\":[\"variable\",[\"template-tag\",\"Email\"]],\"name\":\"Email\",\"slug\":\"Email\"}]','[]',_binary '','v0.53.7 (1cd6e9d)','question',NULL,'2025-06-02 01:50:42.917875','2025-06-02 01:50:45.985505',42,_binary '\0',NULL,NULL,34),(152,'2025-04-15 00:00:40.208289','2025-06-02 01:52:14.584874','Prop. categ erro / tt erros',NULL,'table','{\"database\":33,\"type\":\"native\",\"native\":{\"template-tags\":{\"nivel\":{\"type\":\"text\",\"name\":\"nivel\",\"id\":\"f9dc635f-13e5-4438-8e00-9825faad0f11\",\"display-name\":\"Nivel\"},\"profesor\":{\"type\":\"text\",\"name\":\"profesor\",\"id\":\"6f3c639d-2247-4429-b45e-a4a56c5ceb85\",\"display-name\":\"Profesor\"},\"ano_semestre\":{\"type\":\"text\",\"name\":\"ano_semestre\",\"id\":\"09f2739f-aa11-4699-bf51-fd47b4870517\",\"display-name\":\"Ano Semestre\"},\"horario\":{\"type\":\"text\",\"name\":\"horario\",\"id\":\"72e2ef52-73c9-4629-95ea-a0722c2b075b\",\"display-name\":\"Horario\"},\"corte\":{\"type\":\"text\",\"name\":\"corte\",\"id\":\"7ef1a57b-919a-4650-b0bf-c5f865e275f0\",\"display-name\":\"Corte\"},\"Nome\":{\"type\":\"text\",\"name\":\"Nome\",\"id\":\"e90db8c5-8824-41e4-8bc3-1ccf1838c7c5\",\"display-name\":\"Nome\"},\"Email\":{\"type\":\"text\",\"name\":\"Email\",\"id\":\"f2dd79a2-34cd-4ad6-955c-183874cffb75\",\"display-name\":\"Email\"}},\"query\":\"WITH errores_por_categoria AS (\\n  -- ORTOGRAF√çA\\n  SELECT \'ORTOGRAF\' AS categoria, \\n         SUM(COALESCE(ss, 0) + COALESCE(√ß, 0) + COALESCE(rr, 0) + COALESCE(x, 0) + COALESCE(s, 0)) AS total_erros,\\n         MAX(email) AS email\\n  FROM caracterizacao_escritura\\n  WHERE 1=1\\n    [[AND `N√≠vel` = {{nivel}}]] \\n    [[AND `Professor(a)` = {{profesor}}]] \\n    [[AND ano_semestre = {{ano_semestre}}]] \\n    [[AND `Hor√°rio` = {{horario}}]] \\n    [[AND corte = {{corte}}]]\\n    [[AND `Nome` = {{Nome}}]]\\n    [[AND email = {{Email}}]]\\n\\n  UNION ALL\\n\\n  -- ACENTUACI√ìN\\n  SELECT \'ACENTUAC\' AS categoria, \\n         SUM(COALESCE(acento_grave, 0) + COALESCE(acento_agudo, 0) + COALESCE(acento_circunflexo, 0) + COALESCE(til, 0)) AS total_erros,\\n         MAX(email) AS email\\n  FROM caracterizacao_escritura\\n  WHERE 1=1\\n    [[AND `N√≠vel` = {{nivel}}]] \\n    [[AND `Professor(a)` = {{profesor}}]] \\n    [[AND ano_semestre = {{ano_semestre}}]] \\n    [[AND `Hor√°rio` = {{horario}}]] \\n    [[AND corte = {{corte}}]]\\n    [[AND `Nome` = {{Nome}}]]\\n    [[AND email = {{Email}}]]\\n\\n  UNION ALL\\n\\n  -- CONC. VERBAL\\n  SELECT \'CONC_VERBAL\' AS categoria, \\n         SUM(COALESCE(verbos_regulares, 0) + COALESCE(verbos_irregulares, 0)) AS total_erros,\\n         MAX(email) AS email\\n  FROM caracterizacao_escritura\\n  WHERE 1=1\\n    [[AND `N√≠vel` = {{nivel}}]] \\n    [[AND `Professor(a)` = {{profesor}}]] \\n    [[AND ano_semestre = {{ano_semestre}}]] \\n    [[AND `Hor√°rio` = {{horario}}]] \\n    [[AND corte = {{corte}}]]\\n    [[AND `Nome` = {{Nome}}]]\\n    [[AND email = {{Email}}]]\\n\\n  UNION ALL\\n\\n  -- CONC. NOMINAL\\n  SELECT \'CONC_NOMINAL\' AS categoria, \\n         SUM(COALESCE(genero, 0) + COALESCE(numero, 0)) AS total_erros,\\n         MAX(email) AS email\\n  FROM caracterizacao_escritura\\n  WHERE 1=1\\n    [[AND `N√≠vel` = {{nivel}}]] \\n    [[AND `Professor(a)` = {{profesor}}]] \\n    [[AND ano_semestre = {{ano_semestre}}]] \\n    [[AND `Hor√°rio` = {{horario}}]] \\n    [[AND corte = {{corte}}]]\\n    [[AND `Nome` = {{Nome}}]]\\n    [[AND email = {{Email}}]]\\n\\n  UNION ALL\\n\\n  -- PUNTUACI√ìN\\n  SELECT \'PONTUACAO\' AS categoria, \\n         SUM(COALESCE(virgula, 0) + COALESCE(ponto_seguida, 0) + COALESCE(ponto_paragrafo, 0) + COALESCE(ponto_virgula, 0) + \\n             COALESCE(reticencias, 0) + COALESCE(ponto_interrogacao, 0) + COALESCE(ponto_exclamacao, 0) + COALESCE(travessao, 0) + \\n             COALESCE(aspas, 0) + COALESCE(parenteses, 0)) AS total_erros,\\n         MAX(email) AS email\\n  FROM caracterizacao_escritura\\n  WHERE 1=1\\n    [[AND `N√≠vel` = {{nivel}}]] \\n    [[AND `Professor(a)` = {{profesor}}]] \\n    [[AND ano_semestre = {{ano_semestre}}]] \\n    [[AND `Hor√°rio` = {{horario}}]] \\n    [[AND corte = {{corte}}]]\\n    [[AND `Nome` = {{Nome}}]]\\n    [[AND email = {{Email}}]]\\n\\n  UNION ALL\\n\\n  -- VOCABULARIO\\n  SELECT \'VOCABULARIO\' AS categoria, \\n         SUM(COALESCE(usualidade, 0) + COALESCE(portunhol, 0) + COALESCE(extra_terrestre, 0) + COALESCE(repeticoes_inadequadas, 0) + \\n             COALESCE(ausencia, 0) + COALESCE(excesso, 0) + COALESCE(ordem, 0)) AS total_erros,\\n         MAX(email) AS email\\n  FROM caracterizacao_escritura\\n  WHERE 1=1\\n    [[AND `N√≠vel` = {{nivel}}]] \\n    [[AND `Professor(a)` = {{profesor}}]] \\n    [[AND ano_semestre = {{ano_semestre}}]] \\n    [[AND `Hor√°rio` = {{horario}}]] \\n    [[AND corte = {{corte}}]]\\n    [[AND `Nome` = {{Nome}}]]\