rave + acento_agudo + acento_circunflexo + til)\\r\\n  FROM caracterizacao_escritura\\r\\n  WHERE 1=1\\r\\n    [[AND `N√≠vel` = {{nivel}}]] \\r\\n    [[AND `Professor(a)` = {{profesor}}]] \\r\\n    [[AND `Ano_Semestre` = {{ano_semestre}}]] \\r\\n    [[AND `Hor√°rio` = {{horario}}]] \\r\\n    [[AND `Corte` = {{corte}}]]\\r\\n    [[AND `Nome` = {{Nome}}]]\\r\\n\\r\\n  UNION ALL\\r\\n\\r\\n  -- CONC. VERBAL\\r\\n  SELECT \'CONC_VERBAL\', \\r\\n         SUM(verbos_regulares + verbos_irregulares)\\r\\n  FROM caracterizacao_escritura\\r\\n  WHERE 1=1\\r\\n    [[AND `N√≠vel` = {{nivel}}]] \\r\\n    [[AND `Professor(a)` = {{profesor}}]] \\r\\n    [[AND `Ano_Semestre` = {{ano_semestre}}]] \\r\\n    [[AND `Hor√°rio` = {{horario}}]] \\r\\n    [[AND `Corte` = {{corte}}]]\\r\\n    [[AND `Nome` = {{Nome}}]]\\r\\n\\r\\n  UNION ALL\\r\\n\\r\\n  -- CONC. NOMINAL\\r\\n  SELECT \'CONC_NOMINAL\', \\r\\n         SUM(genero + numero)\\r\\n  FROM caracterizacao_escritura\\r\\n  WHERE 1=1\\r\\n    [[AND `N√≠vel` = {{nivel}}]] \\r\\n    [[AND `Professor(a)` = {{profesor}}]] \\r\\n    [[AND `Ano_Semestre` = {{ano_semestre}}]] \\r\\n    [[AND `Hor√°rio` = {{horario}}]] \\r\\n    [[AND `Corte` = {{corte}}]]\\r\\n    [[AND `Nome` = {{Nome}}]]\\r\\n\\r\\n  UNION ALL\\r\\n\\r\\n  -- PUNTUACI√ìN\\r\\n  SELECT \'PONTUACAO\', \\r\\n         SUM(virgula + ponto_seguida + ponto_paragrafo + ponto_virgula + \\r\\n             reticencias + ponto_interrogacao + ponto_exclamacao + travessao + \\r\\n             aspas + parenteses)\\r\\n  FROM caracterizacao_escritura\\r\\n  WHERE 1=1\\r\\n    [[AND `N√≠vel` = {{nivel}}]] \\r\\n    [[AND `Professor(a)` = {{profesor}}]] \\r\\n    [[AND `Ano_Semestre` = {{ano_semestre}}]] \\r\\n    [[AND `Hor√°rio` = {{horario}}]] \\r\\n    [[AND `Corte` = {{corte}}]]\\r\\n    [[AND `Nome` = {{Nome}}]]\\r\\n\\r\\n  UNION ALL\\r\\n\\r\\n  -- VOCABULARIO\\r\\n  SELECT \'VOCABULARIO\', \\r\\n         SUM(usualidade + portunhol + extra_terrestre + repeticoes_inadequadas + \\r\\n             ausencia + excesso + ordem)\\r\\n  FROM caracterizacao_escritura\\r\\n  WHERE 1=1\\r\\n    [[AND `N√≠vel` = {{nivel}}]] \\r\\n    [[AND `Professor(a)` = {{profesor}}]] \\r\\n    [[AND `Ano_Semestre` = {{ano_semestre}}]] \\r\\n    [[AND `Hor√°rio` = {{horario}}]] \\r\\n    [[AND `Corte` = {{corte}}]]\\r\\n    [[AND `Nome` = {{Nome}}]]\\r\\n)\\r\\n\\r\\nSELECT \\r\\n  categoria,\\r\\n  total_erros,\\r\\n  ROUND((total_erros * 100.0) / NULLIF(SUM(total_erros) OVER (), 0), 2) AS porcentaje\\r\\nFROM errores_por_categoria\\r\\nORDER BY porcentaje DESC;\\r\\n\"}}','{\"table.pivot_column\":\"categoria\",\"table.cell_column\":\"total_erros\",\"pivot_table.column_split\":{\"rows\":[\"total_erros\",\"porcentaje\"],\"columns\":[\"categoria\"],\"values\":[]},\"table.pivot\":false,\"table.columns\":[{\"name\":\"categoria\",\"enabled\":true},{\"name\":\"total_erros\",\"enabled\":true},{\"name\":\"porcentaje\",\"enabled\":true}],\"column_settings\":{\"[\\\"name\\\",\\\"porcentaje\\\"]\":{\"prefix\":\"\",\"show_mini_bar\":false,\"number_style\":\"decimal\",\"suffix\":\"%\"}}}',1,33,NULL,'native',_binary '\0',10,NULL,NULL,_binary '\0',NULL,NULL,'[{\"display_name\":\"categoria\",\"field_ref\":[\"field\",\"categoria\",{\"base-type\":\"type/Text\"}],\"base_type\":\"type/Text\",\"effective_type\":\"type/Text\",\"name\":\"categoria\",\"semantic_type\":null,\"fingerprint\":{\"global\":{\"distinct-count\":6,\"nil%\":0.0},\"type\":{\"type/Text\":{\"percent-json\":0.0,\"percent-url\":0.0,\"percent-email\":0.0,\"percent-state\":0.0,\"average-length\":9.833333333333334}}}},{\"display_name\":\"total_erros\",\"field_ref\":[\"field\",\"total_erros\",{\"base-type\":\"type/Decimal\"}],\"base_type\":\"type/Decimal\",\"effective_type\":\"type/Decimal\",\"name\":\"total_erros\",\"semantic_type\":null,\"fingerprint\":{\"global\":{\"distinct-count\":6,\"nil%\":0.0},\"type\":{\"type/Number\":{\"min\":85.0,\"q1\":162.0,\"q3\":398.0,\"max\":562.0,\"sd\":173.96944176109398,\"avg\":282.833333333