] \\r\\n    [[AND `Ano_Semestre` = {{ano_semestre}}]] \\r\\n    [[AND `Hor√°rio` = {{horario}}]] \\r\\n    [[AND `Corte` = {{corte}}]]\\r\\n\\r\\n  UNION ALL\\r\\n\\r\\n  -- VOCABULARIO\\r\\n  SELECT \'VOCABULARIO\', \\r\\n         SUM(usualidade + portunhol + extra_terrestre + repeticoes_inadequadas + \\r\\n             ausencia + excesso + ordem)\\r\\n  FROM caracterizacao_escritura\\r\\n  WHERE 1=1\\r\\n    [[AND `N√≠vel` = {{nivel}}]] \\r\\n    [[AND `Professor(a)` = {{profesor}}]] \\r\\n    [[AND `Ano_Semestre` = {{ano_semestre}}]] \\r\\n    [[AND `Hor√°rio` = {{horario}}]] \\r\\n    [[AND `Corte` = {{corte}}]]\\r\\n)\\r\\n\\r\\nSELECT \\r\\n  categoria,\\r\\n  total_erros,\\r\\n  ROUND((total_erros * 100.0) / NULLIF(SUM(total_erros) OVER (), 0), 2) AS porcentaje\\r\\nFROM errores_por_categoria\\r\\nORDER BY porcentaje DESC;\\r\\n\"}},\"parameter_mappings\":[],\"display\":\"table\",\"archived_directly\":false,\"collection_preview\":true,\"visualization_settings\":{\"table.pivot_column\":\"categoria\",\"table.cell_column\":\"total_erros\"},\"parameters\":[{\"id\":\"f9dc635f-13e5-4438-8e00-9825faad0f11\",\"type\":\"category\",\"target\":[\"variable\",[\"template-tag\",\"nivel\"]],\"name\":\"Nivel\",\"slug\":\"nivel\"},{\"id\":\"6f3c639d-2247-4429-b45e-a4a56c5ceb85\",\"type\":\"category\",\"target\":[\"variable\",[\"template-tag\",\"profesor\"]],\"name\":\"Profesor\",\"slug\":\"profesor\"},{\"id\":\"09f2739f-aa11-4699-bf51-fd47b4870517\",\"type\":\"category\",\"target\":[\"variable\",[\"template-tag\",\"ano_semestre\"]],\"name\":\"Ano Semestre\",\"slug\":\"ano_semestre\"},{\"id\":\"72e2ef52-73c9-4629-95ea-a0722c2b075b\",\"type\":\"category\",\"target\":[\"variable\",[\"template-tag\",\"horario\"]],\"name\":\"Horario\",\"slug\":\"horario\"},{\"id\":\"7ef1a57b-919a-4650-b0bf-c5f865e275f0\",\"type\":\"category\",\"target\":[\"variable\",[\"template-tag\",\"corte\"]],\"name\":\"Corte\",\"slug\":\"corte\"}],\"dashboard_id\":34}',_binary '\0',_binary '',NULL,_binary '\