\\r\\n    [[AND `Ano_Semestre` = {{ano_semestre}}]] \\r\\n    [[AND `Hor√°rio` = {{horario}}]] \\r\\n    [[AND `Corte` = {{corte}}]]\\r\\n\\r\\n  UNION ALL\\r\\n\\r\\n  -- PUNTUACI√ìN\\r\\n  SELECT \'PONTUACAO\', \\r\\n         SUM(virgula + ponto_seguida + ponto_paragrafo + ponto_virgula + \\r\\n             reticencias + ponto_interrogacao + ponto_exclamacao + travessao + \\r\\n             aspas + parenteses)\\r\\n  FROM caracterizacao_escritura\\r\\n  WHERE 1=1\\r\\n    [[AND `N√≠vel` = {{nivel}}]] \\r\\n    [[AND `Professor(a)` = {{profesor}}]] \\r\\n    [[AND `Ano_Semestre` = {{ano_semestre}}]] \\r\\n    [[AND `Hor√°rio` = {{horario}}]] \\r\\n    [[AND `Corte` = {{corte}}]]\\r\\n\\r\\n  UNION ALL\\r\\n\\r\\n  -- VOCABULARIO\\r\\n  SELECT \'VOCABULARIO\', \\r\\n         SUM(usualidade + portunhol + extra_terrestre + repeticoes_inadequadas + \\r\\n             ausencia + excesso + ordem)\\r\\n  FROM caracterizacao_escritura\\r\\n  WHERE 1=1\\r\\n    [[AND `N√≠vel` = {{nivel}}]] \\r\\n    [[AND `Professor(a)` = {{profesor}}]] \\r\\n    [[AND `Ano_Semestre` = {{ano_semestre}}]] \\r\\n    [[AND `Hor√°rio` = {{horario}}]] \\r\\n    [[AND `Corte` = {{corte}}]]\\r\\n)\\r\\n\\r\\nSELECT \\r\\n  categoria,\\r\\n  total_erros,\\r\\n  ROUND((total_erros * 100.0) / NULLIF(SUM(total_erros) OVER (), 0), 2) AS porcentaje\\r\\nFROM errores_por_categoria\\r\\nORDER BY porcentaje DESC;\\r\\n\"}},\"parameter_mappings\":[],\"display\":\"table\",\"archived_directly\":false,\"collection_preview\":true,\"visualization_settings\":{\"table.pivot_column\":\"categoria\",\"table.cell_column\":\"total_erros\",\"pivot_table.column_split\":{\"rows\":[\"total_erros\",\"porcentaje\"],\"columns\":[\"categoria\"],\"values\":[]}},\"parameters\":[{\"id\":\"f9dc635f-13e5-4438-8e00-9825faad0f11\",\"type\":\"category\",\"target\":[\"variable\",[\"template-tag\",\"nivel\"]],\"name\":\"Nivel\",\"slug\":\"nivel\"},{\"id\":\"6f3c639d-2247-4429-b45e-a4a56c5ceb85\",\"type\":\"category\",\"target\":[\"varia