rizacao_escritura`\\r\\n  WHERE 1=1\\r\\n    [[AND `N√≠vel` = {{nivel}}]]\\r\\n    [[AND `Professor(a)` = {{profesor}}]]\\r\\n    [[AND `Ano_Semestre` = {{ano_semestre}}]]\\r\\n    [[AND `Hor√°rio` = {{horario}}]]\\r\\n    [[AND `Corte` = {{corte}}]]\\r\\n  GROUP BY `Professor`\\r\\n),\\r\\n\\r\\n-- CTE para calcular total general\\r\\ntotal_general AS (\\r\\n  SELECT\\r\\n    \'Total general\' AS Professor,\\r\\n    SUM(\\r\\n      `ss` + `√ß` + `rr` + `x` + `s` +\\r\\n      `acento_grave` + `acento_agudo` + `acento_circunflexo` + `til` +\\r\\n      `verbos_regulares` + `verbos_irregulares` +\\r\\n      `genero` + `numero` +\\r\\n      `virgula` + `ponto_seguida` + `ponto_paragrafo` + `ponto_virgula` +\\r\\n      `reticencias` + `ponto_interrogacao` + `ponto_exclamacao` +\\r\\n      `travessao` + `aspas` + `parenteses` +\\r\\n      `usualidade` + `portunhol` + `extra_terrestre` +\\r\\n      `repeticoes_inadequadas` + `ausencia` + `excesso` + `ordem`\\r\\n    ) / COUNT(*) AS promedio_errores\\r\\n  FROM `caracterizacao_escritura`\\r\\n  WHERE 1=1\\r\\n    [[AND `N√≠vel` = {{nivel}}]]\\r\\n    [[AND `Professor(a)` = {{profesor}}]]\\r\\n    [[AND `Ano_Semestre` = {{ano_semestre}}]]\\r\\n    [[AND `Hor√°rio` = {{horario}}]]\\r\\n    [[AND `Corte` = {{corte}}]]\\r\\n)\\r\\n\\r\\n-- Unimos ambos resultados\\r\\nSELECT * FROM promedio_por_profesor\\r\\nUNION ALL\\r\\nSELECT * FROM total_general\\r\\nORDER BY\\r\\n  CASE \\r\\n    WHEN Professor = \'Total general\' THEN 1\\r\\n    ELSE 2\\r\\n  END,\\r\\n  Professor;\\r\\n\\r\\n\\r\\n\"}},\"parameter_mappings\":[],\"display\":\"row\",\"archived_directly\":false,\"collection_preview\":true,\"visualization_settings\":{\"graph.series_order\":null,\"graph.series_order_dimension\":null,\"graph.label_value_formatting\":\"compact\",\"graph.dimensions\":[\"Professor\",\"promedio_errores\"],\"series_settings\":{\"19\":{\"color\":\"#999AC4\"},\"promedio_errores\":{\"color\":\"#A7D07C\"},\"total_general\":{\"color\":\"#F9D45C\"},\"23