o_Semestre` = {{ano_semestre}}]] \\n  [[AND `Hor√°rio` = {{horario}}]] \\n  [[AND `Corte` = {{corte}}]]\\n  [[AND `Email` = {{Email}}]]\\nUNION ALL\\n\\n-- PUNTUACI√ìN\\nSELECT \'PONTUACAO\', \\n       SUM(virgula + ponto_seguida + ponto_paragrafo + ponto_virgula + \\n           reticencias + ponto_interrogacao + ponto_exclamacao + travessao + \\n           aspas + parenteses)\\nFROM caracterizacao_escritura\\nWHERE 1=1\\n  [[AND `N√≠vel` = {{nivel}}]] \\n  [[AND `Professor(a)` = {{profesor}}]] \\n  [[AND `Ano_Semestre` = {{ano_semestre}}]] \\n  [[AND `Hor√°rio` = {{horario}}]] \\n  [[AND `Corte` = {{corte}}]]\\n  [[AND `Email` = {{Email}}]]\\n\\nUNION ALL\\n\\n-- VOCABULARIO\\nSELECT \'VOCABULARIO\', \\n       SUM(usualidade + portunhol + extra_terrestre + repeticoes_inadequadas + \\n           ausencia + excesso + ordem)\\nFROM caracterizacao_escritura\\nWHERE 1=1\\n  [[AND `N√≠vel` = {{nivel}}]] \\n  [[AND `Professor(a)` = {{profesor}}]] \\n  [[AND `Ano_Semestre` = {{ano_semestre}}]] \\n  [[AND `Hor√°rio` = {{horario}}]] \\n  [[AND `Corte` = {{corte}}]]\\n  [[AND `Email` = {{Email}}]]\\n\"}},\"parameter_mappings\":[],\"display\":\"bar\",\"archived_directly\":false,\"collection_preview\":true,\"visualization_settings\":{\"graph.dimensions\":[\"categoria\"],\"graph.show_values\":true,\"graph.x_axis.scale\":\"ordinal\",\"graph.metrics\":[\"total_erros\"]},\"parameters\":[{\"id\":\"1fe325b8-d761-487b-b3c8-1c49c1c933c0\",\"type\":\"category\",\"target\":[\"variable\",[\"template-tag\",\"nivel\"]],\"name\":\"Nivel\",\"slug\":\"nivel\"},{\"id\":\"254d24f6-152a-47c6-be47-fa56a46ecf15\",\"type\":\"category\",\"target\":[\"variable\",[\"template-tag\",\"profesor\"]],\"name\":\"Profesor\",\"slug\":\"profesor\"},{\"id\":\"ad7ff0b1-a757-45f8-9ede-0f0fa9015cb6\",\"type\":\"category\",\"target\":[\"variable\",[\"template-tag\",\"ano_semestre\"]],\"name\":\"Ano Semestre\",\"slug\":\"ano_semestre\"},{\"id\":\"568a8714-2b9e-446a-aeb3-c5adeef72c38\",\"type\":\"category\",\"target\"