ses`, 0) +\\n      COALESCE(`usualidade`, 0) + COALESCE(`portunhol`, 0) + COALESCE(`extra_terrestre`, 0) +\\n      COALESCE(`repeticoes_inadequadas`, 0) + COALESCE(`ausencia`, 0) + COALESCE(`excesso`, 0) + COALESCE(`ordem`, 0)\\n    ) / COUNT(*) AS promedio_errores\\n  FROM `caracterizacao_escritura`\\n  WHERE 1=1\\n    [[AND `N√≠vel` = {{nivel}}]]\\n    [[AND `Professor(a)` = {{profesor}}]]\\n    [[AND ano_semestre = {{ano_semestre}}]]\\n    [[AND `Hor√°rio` = {{horario}}]]\\n    [[AND corte = {{corte}}]]\\n    [[AND email = {{Email}}]]\\n  GROUP BY `Professor(a)`\\n),\\n\\n-- CTE para calcular total general\\ntotal_general AS (\\n  SELECT\\n    \'Total general\' AS Professor,\\n    SUM(\\n      COALESCE(`ss`, 0) + COALESCE(`√ß`, 0) + COALESCE(`rr`, 0) + COALESCE(`x`, 0) + COALESCE(`s`, 0) +\\n      COALESCE(`acento_grave`, 0) + COALESCE(`acento_agudo`, 0) + COALESCE(`acento_circunflexo`, 0) + COALESCE(`til`, 0) +\\n      COALESCE(`verbos_regulares`, 0) + COALESCE(`verbos_irregulares`, 0) +\\n      COALESCE(`genero`, 0) + COALESCE(`numero`, 0) +\\n      COALESCE(`virgula`, 0) + COALESCE(`ponto_seguida`, 0) + COALESCE(`ponto_paragrafo`, 0) + COALESCE(`ponto_virgula`, 0) +\\n      COALESCE(`reticencias`, 0) + COALESCE(`ponto_interrogacao`, 0) + COALESCE(`ponto_exclamacao`, 0) +\\n      COALESCE(`travessao`, 0) + COALESCE(`aspas`, 0) + COALESCE(`parenteses`, 0) +\\n      COALESCE(`usualidade`, 0) + COALESCE(`portunhol`, 0) + COALESCE(`extra_terrestre`, 0) +\\n      COALESCE(`repeticoes_inadequadas`, 0) + COALESCE(`ausencia`, 0) + COALESCE(`excesso`, 0) + COALESCE(`ordem`, 0)\\n    ) / COUNT(*) AS promedio_errores\\n  FROM `caracterizacao_escritura`\\n  WHERE 1=1\\n    [[AND `N√≠vel` = {{nivel}}]]\\n    [[AND `Professor(a)` = {{profesor}}]]\\n    [[AND ano_semestre = {{ano_semestre}}]]\\n    [[AND `Hor√°rio` = {{horario}}]]\\n    [[AND corte = {{corte}}]]\\n    [[AND email = {{Email}}]]\\n)\\n\\n-- Unimos ambos resultados\\nSELECT * FROM promedio_por_profesor\\nUNION ALL\\nSELECT * FROM total_general\\nORDER BY\\n  CASE \\n    WHEN Professor = \'Total general\' THEN 1\\n    ELSE 0\\n  END,\\n  Professor;\"}},\"parameter_mappings\":[],\"display\":\"row\",\"archived_directly\":false,\"collection_preview\":true,\"visualization_settings\":{\"graph.series_order\":null,\"graph.series_order_dimension\":null,\"graph.label_value_formatting\":\"compact\",\"graph.dimensions\":[\"Professor\",\"promedio_errores\"],\"series_settings\":{\"19\":{\"color\":\"#999AC4\"},\"promedio_errores\":{\"color\":\"#A7D07C\"},\"total_general\":{\"color\":\"#F9D45C\"},\"23.57\":{\"color\":\"#F9D45C\"},\"23.63\":{\"color\":\"#A7D07C\"}},\"graph.show_values\":true,\"graph.metrics\":[\"promedio_errores\"]},\"parameters\":[{\"id\":\"3b5b6680-e828-4ccc-9a09-25bbc7d590d9\",\"type\":\"category\",\"target\":[\"variable\",[\"template-tag\",\"nivel\"]],\"name\":\"Nivel\",\"slug\":\"nivel\"},{\"id\":\"12a94bee-44de-4f89-b773-407494c8918e\",\"type\":\"category\",\"target\":[\"variable\",[\"template-tag\",\"profesor\"]],\"name\":\"Profesor\",\"slug\":\"profesor\"},{\"id\":\"bcde2905-755a-4a5c-84c2-441c28744ada\",\"type\":\"category\",\"target\":[\"variable\",[\"template-tag\",\"ano_semestre\"]],\"name\":\"Ano Semestre\",\"slug\":\"ano_semestre\"},{\"id\":\"086b1260-1422-42d2-a308-3cbc05870e10\",\"type\":\"category\",\"target\":[\"variable\",[\"template-tag\",\"horario\"]],\"name\":\"Horario\",\"slug\":\"horario\"},{\"id\":\"f43b07e6-d2cd-4111-aa65-7efbda7090eb\",\"type\":\"category\",\"target\":[\"variable\",[\"template-tag\",\"corte\"]],\"name\":\"Corte\",\"slug\":\"corte\"},{\"id\":\"020395e6-6711-4393-b787-917bea885c64\",\"type\":\"category\",\"target\":[\"variable\",[\"template-tag\",\"Email\"]],\"name\":\"Email\",\"slug\":\"Email\"}],\"dashboard_id\":34}',_binary '\0',_binary '\0',NULL,_binary '','v0.54.4 (33dddaa)'),(533,'Card',143,1,'2025-06-02 01:46:22.000000','{\"description\":null,\"archived\":false,\"collection_position\":null,\"source_card_id\":null,\"table_id