critura\\nWHERE 1=1\\n  [[AND `N√≠vel` = {{nivel}}]] \\n  [[AND `Professor(a)` = {{profesor}}]] \\n  [[AND `Ano_Semestre` = {{ano_semestre}}]] \\n  [[AND `Hor√°rio` = {{horario}}]] \\n  [[AND `Corte` = {{corte}}]]\\n  [[AND `Nome` = {{Nome}}]]\\n      [[AND email = {{Email}}]]\\n\\n\\nUNION ALL\\n\\n-- CONCORDANCIA NOMINAL\\nSELECT \'CONC_NOMINAL\', \\n       SUM(genero + numero)\\nFROM caracterizacao_escritura\\nWHERE 1=1\\n  [[AND `N√≠vel` = {{nivel}}]] \\n  [[AND `Professor(a)` = {{profesor}}]] \\n  [[AND `Ano_Semestre` = {{ano_semestre}}]] \\n  [[AND `Hor√°rio` = {{horario}}]] \\n  [[AND `Corte` = {{corte}}]]\\n  [[AND `Nome` = {{Nome}}]]\\n      [[AND email = {{Email}}]]\\n\\n\\nUNION ALL\\n\\n-- PUNTUACI√ìN\\nSELECT \'PONTUACAO\', \\n       SUM(virgula + ponto_seguida + ponto_paragrafo + ponto_virgula + \\n           reticencias + ponto_interrogacao + ponto_exclamacao + travessao + \\n           aspas + parenteses)\\nFROM caracterizacao_escritura\\nWHERE 1=1\\n  [[AND `N√≠vel` = {{nivel}}]] \\n  [[AND `Professor(a)` = {{profesor}}]] \\n  [[AND `Ano_Semestre` = {{ano_semestre}}]] \\n  [[AND `Hor√°rio` = {{horario}}]] \\n  [[AND `Corte` = {{corte}}]]\\n  [[AND `Nome` = {{Nome}}]]\\n      [[AND email = {{Email}}]]\\n\\n\\nUNION ALL\\n\\n-- VOCABULARIO\\nSELECT \'VOCABULARIO\', \\n       SUM(usualidade + portunhol + extra_terrestre + repeticoes_inadequadas + \\n           ausencia + excesso + ordem)\\nFROM caracterizacao_escritura\\nWHERE 1=1\\n  [[AND `N√≠vel` = {{nivel}}]] \\n  [[AND `Professor(a)` = {{profesor}}]] \\n  [[AND `Ano_Semestre` = {{ano_semestre}}]] \\n  [[AND `Hor√°rio` = {{horario}}]] \\n  [[AND `Corte` = {{corte}}]]\\n  [[AND `Nome` = {{Nome}}]]\\n      [[AND email = {{Email}}]]\\n\"}},\"parameter_mappings\":[],\"display\":\"bar\",\"archived_directly\":false,\"collection_preview\":true,\"visualization_settings\":{\"graph.dimensions\":[\"categoria\"],\"graph.show_values\":true,\"graph.x_axis.title_text\":\"CATEGORIA\",\"graph.x_axis.scale\":\"ordinal\",\"graph.metrics\":[\"total_erros\"]},\"parameters\":[{\"id\":\"e03c1a21-7ca2-4f66-933c-d844f0e9cbbd\",\"type\":\"category\",\"target\":[\"variable\",[\"template-tag\",\"nivel\"]],\"name\":\"Nivel\",\"slug\":\"nivel\"},{\"id\":\"c779d0ce-0dce-4c00-9fd0-7341c8f9d41b\",\"type\":\"category\",\"target\":[\"variable\",[\"template-tag\",\"profesor\"]],\"name\":\"Profesor\",\"slug\":\"profesor\"},{\"id\":\"1f3488eb-a740-456c-8d4e-b43151c942f2\",\"type\":\"category\",\"target\":[\"variable\",[\"template-tag\",\"ano_semestre\"]],\"name\":\"Ano Semestre\",\"slug\":\"ano_semestre\"},{\"id\":\"ec5445a9-48e0-4d4f-8972-11034593c725\",\"type\":\"category\",\"target\":[\"variable\",[\"template-tag\",\"horario\"]],\"name\":\"Horario\",\"slug\":\"horario\"},{\"id\":\"f2b61f39-273d-40a2-bae8-2855876e61e2\",\"type\":\"category\",\"target\":[\"variable\",[\"template-tag\",\"corte\"]],\"name\":\"Corte\",\"slug\":\"corte\"},{\"id\":\"a185d68f-4d3f-41bc-abcf-a61c8b65af38\",\"type\":\"category\",\"target\":[\"variable\",[\"template-tag\",\"Nome\"]],\"name\":\"Nome\",\"slug\":\"Nome\"},{\"id\":\"92b0d7bf-e31d-47bc-929a-4aff995b5d58\",\"type\":\"category\",\"target\":[\"variable\",[\"template-tag\",\"Email\"]],\"name\":\"Email\",\"slug\":\"Email\"}],\"dashboard_id\":34}',_binary '\0',_binary '\0',NULL,_binary '','v0.54.4 (33dddaa)'),(541,'Dashboard',34,1,'2025-06-02 01:52:15.000000','{\"description\":null,\"archived\":false,\"collection_position\":null,\"tabs\":[{\"id\":35,\"dashboard_id\":34,\"name\":\"CATEG ERROS E N√çVEIS\",\"position\":0},{\"id\":65,\"dashboard_id\":34,\"name\":\"CATEG ERROS E HOR√ÅRIOS\",\"position\":1},{\"id\":97,\"dashboard_id\":34,\"name\":\"CATEG ERROS E PROFESSORES\",\"position\":2},{\"id\":98,\"dashboard_id\":34,\"name\":\"CATEG E TIPOS DE ERROS\",\"position\":3},{\"id\":99,\"dashboard_id\":34,\"name\":\"CATEG ERROS E ESTUD\",\"position\":4}],\"enable_embedding\":true,\"collection_id\":10,\"name\":\"Caracterizacion Escritura\",\"width\":\"fixed\",\"embedding_p