INSERT INTO `setting` VALUES ('admin-email','cristhianvasco@gmail.com'),('analytics-uuid','cec94758-7fa6-4d30-b7cf-aa082fc8468c'),('anon-tracking-enabled','true'),('embedding-secret-key','d97dd1c77980a6109a01efa565fdeda607a86c26333d03dcae2dcada556af89c'),('enable-embedding-static','true'),('encryption-check','unencrypted'),('entity-id-translation-counter','{\"ok\":0,\"not-found\":0,\"invalid-format\":0}'),('example-dashboard-id','1'),('instance-creation','2025-03-19T16:31:31.605954Z'),('redirect-all-requests-to-https','false'),('settings-last-updated','2025-06-02 00:30:39'),('setup-token','f08d013c-92bb-4c1c-bc7a-6a4376a10388'),('show-static-embed-terms','false'),('site-locale','es'),('site-name','Ean'),('site-url','http://localhost:3000'),('site-uuid','9ead8e9e-a592-49eb-ba65-11fc3e540afd'),('site-uuid-for-version-info-fetching','fea5a5a8-0d8c-4308-a2be-642c19416f79'),('startup-time-millis','3533'),('version-info','{\"latest\":{\"version\":\"v0.54.9\",\"released\":\"2025-05-20\",\"patch\":true,\"highlights\":[\"chore: add bpander as a team member\",\"Bump HoneySQL\",\"Fix tooltip flakes\",\"revert and disable entity-id backfill\",\"cljs: Fix obscenely large schema expansions\",\"Fix menu text on sharing and subscription menu\",\"Pivot Table - We\'re limiting downloads to 10k rows\",\"cljs: Don\'t require cljs.pprint in :cljs-release mode to reduce bundle size\",\"Pivot Table - Total being converted to rows instead of column\",\"Dashboard subscription renders empty row when there are no parameters\",\"docs(sdk): Update SDK version to 0.54.11\",\"fix flaky timelines spec\",\"Refresh temporary tokens\",\"fix(sdk): Fix `fonts.styled.ts` braces\",\"Prefix all of our log context with mb-\",\"Fix wrong names of CSS module files\",\"Do not transform :has css selectors by Post CSS\",\"feat(sdk): Reduce bundle size by avoiding the usage of `jsrsasign` dependency\",\"Fix ModalHeader back button position\",\"fix legend flaky spec\",\"Some Notifications Aren‚Äôt Scheduled if Se